import{_ as e,o as i,c as t,a2 as s}from"./chunks/framework.DCVnL8g5.js";const p=JSON.parse('{"title":"Buenas practicas de Bash","description":"","frontmatter":{},"headers":[],"relativePath":"devops/bash/08-buenas-practicas.md","filePath":"devops/bash/08-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),o={name:"devops/bash/08-buenas-practicas.md"};function r(d,a,l,n,c,h){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="buenas-practicas-de-bash" tabindex="-1">Buenas practicas de Bash <a class="header-anchor" href="#buenas-practicas-de-bash" aria-label="Permalink to &quot;Buenas practicas de Bash&quot;">​</a></h1><p>Guia rapida para escribir shell scripts mantenibles y seguros en entornos DevOps.</p><h2 id="estilo-y-legibilidad" tabindex="-1">Estilo y legibilidad <a class="header-anchor" href="#estilo-y-legibilidad" aria-label="Permalink to &quot;Estilo y legibilidad&quot;">​</a></h2><ul><li>Indentacion consistente (2 espacios).</li><li>Comillas en expansiones: <code>&quot;$var&quot;</code>.</li><li><code>[[ ]]</code> para tests en bash.</li><li>Nombres claros: <code>backup_database</code>, no <code>bd</code>.</li><li>Comentarios solo en logica no obvia.</li></ul><h2 id="herramientas" tabindex="-1">Herramientas <a class="header-anchor" href="#herramientas" aria-label="Permalink to &quot;Herramientas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Herramienta</th><th>Uso</th></tr></thead><tbody><tr><td><strong>shellcheck</strong></td><td>Lint estatico</td></tr><tr><td><strong>shfmt</strong></td><td>Formateo</td></tr><tr><td><strong>bats</strong></td><td>Tests de shell</td></tr><tr><td><strong>bashdb</strong></td><td>Depuracion</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shellcheck</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy.sh</span></span></code></pre></div><h2 id="seguridad" tabindex="-1">Seguridad <a class="header-anchor" href="#seguridad" aria-label="Permalink to &quot;Seguridad&quot;">​</a></h2><ul><li><code>set -u</code> evita <code>rm -rf &quot;$EMPTY&quot;/</code>.</li><li>No uses <code>eval</code> con input usuario.</li><li>Sanitiza argumentos antes de SQL/curl.</li><li>Permisos minimos (usuario dedicado en cron).</li><li>No guardes passwords en scripts; usa secret manager o env inyectado.</li></ul><h2 id="portabilidad" tabindex="-1">Portabilidad <a class="header-anchor" href="#portabilidad" aria-label="Permalink to &quot;Portabilidad&quot;">​</a></h2><ul><li><code>#!/usr/bin/env bash</code> para bash.</li><li>Si necesitas POSIX, usa <code>#!/bin/sh</code> y evita arrays bash.</li><li>En macOS, prueba <code>date</code> y <code>sed</code> (difieren de GNU).</li><li>En CI, fija imagen (<code>ubuntu-latest</code>).</li></ul><h2 id="cuando-no-usar-bash" tabindex="-1">Cuando NO usar Bash <a class="header-anchor" href="#cuando-no-usar-bash" aria-label="Permalink to &quot;Cuando NO usar Bash&quot;">​</a></h2><ul><li>Logica compleja -&gt; Python, Go, TypeScript.</li><li>Parsing JSON/HTML pesado -&gt; <code>jq</code>, Python.</li><li>API REST elaborada -&gt; SDK o curl + jq con cuidado.</li><li>Estado y concurrencia compleja -&gt; servicio proper.</li></ul><p>Bash es pegamento entre CLIs, no lenguaje de aplicacion grande.</p><h2 id="integracion-con-el-stack" tabindex="-1">Integracion con el stack <a class="header-anchor" href="#integracion-con-el-stack" aria-label="Permalink to &quot;Integracion con el stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tarea</th><th>Recurso</th></tr></thead><tbody><tr><td>CI/CD</td><td><a href="./../cicd/01-introduccion-y-principios">CI/CD</a></td></tr><tr><td>GitHub Actions</td><td><a href="./../../cloud/github-actions/01-introduccion-a-workflows">GitHub Actions</a></td></tr><tr><td>SSH remoto</td><td><a href="./../ssh/01-introduccion-y-claves">SSH</a></td></tr><tr><td>Ansible</td><td><a href="./../ansible/01-introduccion-e-inventarios">Ansible</a></td></tr><tr><td>Terminal</td><td><a href="./../../herramientas/terminal/01-introduccion-y-navegacion">Terminal</a></td></tr></tbody></table><h2 id="checklist-de-script-listo-para-prod" tabindex="-1">Checklist de script listo para prod <a class="header-anchor" href="#checklist-de-script-listo-para-prod" aria-label="Permalink to &quot;Checklist de script listo para prod&quot;">​</a></h2><ul><li>[ ] <code>set -euo pipefail</code></li><li>[ ] Shebang correcto</li><li>[ ] Uso documentado</li><li>[ ] Variables validadas</li><li>[ ] Rutas absolutas desde script dir</li><li>[ ] Logs a stdout/stderr o archivo</li><li>[ ] Exit codes significativos</li><li>[ ] shellcheck sin errores criticos</li><li>[ ] Probado en entorno tipo produccion</li></ul><h2 id="errores-de-veteranos-que-siguen-pasando" tabindex="-1">Errores de veteranos que siguen pasando <a class="header-anchor" href="#errores-de-veteranos-que-siguen-pasando" aria-label="Permalink to &quot;Errores de veteranos que siguen pasando&quot;">​</a></h2><ul><li>Script de 800 lineas sin funciones.</li><li>Copy-paste de Stack Overflow sin <code>set -e</code>.</li><li>Cron que falla silenciosamente anos.</li><li>Depender de estado global en <code>/tmp</code> sin lock.</li><li>Mezclar bash y zsh syntax.</li></ul><h2 id="cierre" tabindex="-1">Cierre <a class="header-anchor" href="#cierre" aria-label="Permalink to &quot;Cierre&quot;">​</a></h2><p>Bash sigue siendo indispensable en DevOps: rapido, universal y perfecto para automatizar lo que ya haces en terminal. Escribelo con disciplina (modo estricto, shellcheck, funciones pequenas) y delega logica pesada a lenguajes con mejor soporte para datos y tests.</p>',22)])])}const b=e(o,[["render",r]]);export{p as __pageData,b as default};
